1	/**
2	 * Shared contract between the chat panel, the voice front end and the 3D viewer.
3	 * The backend proposes a spoken reply plus viewer actions; the browser executes them.
4	 * Voice (speech-to-text / text-to-speech) is Gradium by default and can be replaced through setVoice(); see window.brickvision.
5	 */
6	import { post } from './api';
7	import { gradiumVoice, VoiceUnavailable } from './gradiumVoice';
8	
9	export type ViewerAction =
10	  | { type: 'go_to_step'; step: number }
11	  | { type: 'play_steps'; step: number; count: number; narrations: string[] }
12	  | { type: 'rotate'; direction: 'left' | 'right' | 'up' | 'down'; degrees: number }
13	  | { type: 'zoom'; direction: 'in' | 'out' }
14	  | { type: 'reset_view' } | { type: 'replay_step' } | { type: 'stop' };
15	
16	export interface ViewerContext {
17	  set_number: string; guide: string; current_step: number; total_steps: number; playing: boolean;
18	  steps: { step: number; instructions: string[]; pieces: string[] }[];
19	}
20	export interface ViewerController { context(): ViewerContext; run(action: ViewerAction): Promise<void>; }
21	export interface ChatTurn { role: 'user' | 'assistant'; text: string; }
22	export interface AgentReply { reply: string; actions: ViewerAction[]; }
23	
24	const int = (value: unknown, fallback: number) => Number.isFinite(Number(value)) ? Math.trunc(Number(value)) : fallback;
25	/** Model output is untrusted: keep only well-formed actions. */
26	export function parseActions(value: unknown): ViewerAction[] {
27	  if (!Array.isArray(value)) return [];
28	  const actions: ViewerAction[] = [];
29	  for (const raw of value) {
30	    const item = (raw ?? {}) as Record<string, unknown>;
31	    switch (item.type) {
32	      case 'go_to_step': actions.push({ type: 'go_to_step', step: Math.max(1, int(item.step, 1)) }); break;
33	      case 'play_steps': actions.push({ type: 'play_steps', step: Math.max(1, int(item.step, 1)), count: Math.max(1, Math.min(12, int(item.count, 1))),
34	        narrations: Array.isArray(item.narrations) ? item.narrations.filter((line): line is string => typeof line === 'string') : [] }); break;
35	      case 'rotate': if (['left','right','up','down'].includes(item.direction as string)) actions.push({ type: 'rotate',
36	        direction: item.direction as 'left', degrees: Math.max(5, Math.min(720, Math.abs(Number(item.degrees)) || 90)) }); break;
37	      case 'zoom': if (item.direction === 'in' || item.direction === 'out') actions.push({ type: 'zoom', direction: item.direction }); break;
38	      case 'reset_view': case 'replay_step': case 'stop': actions.push({ type: item.type }); break;
39	    }
40	  }
41	  return actions;
42	}
43	export async function askAgent(messages: ChatTurn[], viewer: ViewerContext): Promise<AgentReply> {
44	  const body = await post<{ reply?: unknown; actions?: unknown }>('/chat', { messages, viewer });
45	  return { reply: typeof body.reply === 'string' ? body.reply : '', actions: parseActions(body.actions) };
46	}
47	export function describeAction(action: ViewerAction): string {
48	  switch (action.type) {
49	    case 'go_to_step': return `→ Step ${action.step}`;
50	    case 'play_steps': return action.count > 1 ? `▶ Steps ${action.step}–${action.step + action.count - 1}` : `▶ Step ${action.step}`;
51	    case 'rotate': return `↻ ${action.direction} ${Math.round(action.degrees)}°`;
52	    case 'zoom': return action.direction === 'in' ? '＋ Zoom in' : '－ Zoom out';
53	    case 'reset_view': return '⌖ Reset view';
54	    case 'replay_step': return '↺ Replay';
55	    case 'stop': return '■ Stop';
56	  }
57	}
58	
59	/** Voice plug-in point. speak() must resolve when the audio has finished (or was stopped). */
60	export interface VoiceAdapter {
61	  speak(text: string): Promise<void>; stop(): void;
62	  /** Tap-to-talk: resolves with the transcript once the speaker is done; onPartial receives the text heard so far. */
63	  listen?(onPartial?: (text: string) => void): Promise<string>;
64	  stopListening?(): void;
65	}
66	type Recognition = { lang: string; interimResults: boolean; start(): void; stop(): void;
67	  onresult: ((event: { results: { 0: { transcript: string } }[] }) => void) | null; onerror: ((event: { error: string }) => void) | null; onend: (() => void) | null };
68	let recognition: Recognition | null = null;
69	/** Browser speech: the fallback when Gradium is not available. */
70	const browserVoice: Required<VoiceAdapter> = {
71	  speak: text => new Promise(resolve => {
72	    if (!('speechSynthesis' in window)) { resolve(); return; }
73	    const utterance = new SpeechSynthesisUtterance(text); utterance.rate = 1.05;
74	    utterance.onend = utterance.onerror = () => resolve();
75	    speechSynthesis.cancel(); speechSynthesis.speak(utterance);
76	  }),
77	  stop: () => { if ('speechSynthesis' in window) speechSynthesis.cancel(); },
78	  // Browser recognition only reports the final result here, so onPartial is ignored.
79	  listen: () => new Promise((resolve, reject) => {
80	    const scope = window as unknown as Record<string, (new () => Recognition) | undefined>;
81	    const Ctor = scope.SpeechRecognition ?? scope.webkitSpeechRecognition;
82	    if (!Ctor) { reject(new Error('Voice input is not available in this browser yet. Type instead!')); return; }
83	    const current = new Ctor(); current.lang = 'en-US'; current.interimResults = false;
84	    current.onresult = event => resolve(event.results[0][0].transcript);
85	    current.onerror = event => reject(new Error(`I could not hear that (${event.error}).`));
86	    current.onend = () => { if (recognition === current) recognition = null; resolve(''); };
87	    recognition = current; current.start();
88	  }),
89	  stopListening: () => recognition?.stop(),
90	};
91	/** Default voice: Gradium, switching to browser speech for the rest of the session once Gradium proves unavailable. */
92	let spoken = 0;
93	let gradiumDownUntil = 0; // One network blip must not downgrade the whole session: retry Gradium after a cool-off.
94	async function withFallback<T>(run: (voice: Required<VoiceAdapter>) => Promise<T>): Promise<T> {
95	  let reason: VoiceUnavailable | null = null;
96	  if (Date.now() >= gradiumDownUntil) {
97	    try { return await run(gradiumVoice); }
98	    catch (error) { if (!(error instanceof VoiceUnavailable)) throw error; reason = error; gradiumDownUntil = Date.now() + 20000; }
99	  }
100	  // If the browser cannot do it either, report why Gradium was unavailable: that is the cause worth fixing.
101	  try { return await run(browserVoice); } catch (error) { throw reason ?? error; }
102	}
103	const defaultVoice: Required<VoiceAdapter> = {
104	  // A line that was stopped while Gradium was still failing over must not start again on the browser voice.
105	  speak: text => { const mine = ++spoken; return withFallback(voice => mine === spoken ? voice.speak(text) : Promise.resolve()); },
106	  stop: () => { spoken++; gradiumVoice.stop(); browserVoice.stop(); },
107	  listen: onPartial => withFallback(voice => voice.listen(onPartial)),
108	  stopListening: () => { gradiumVoice.stopListening(); browserVoice.stopListening(); },
109	};
110	const VOICE_KEY = 'brickvisionx:voice', VOICE_EVENT = 'brickvision:voice';
111	let adapter: VoiceAdapter = defaultVoice;
112	// Voice starts on at every page load: a mute left over from an earlier visit must not silence a demo.
113	let muted = false;
114	try { localStorage.removeItem(VOICE_KEY); } catch { /* Storage may be unavailable. */ }
115	let openMics = 0;
116	let cancel: (() => void) | null = null;
117	export const isMuted = () => muted;
118	export function setMuted(value: boolean) {
119	  if (value) stopSpeaking();
120	  muted = value;
121	  window.dispatchEvent(new Event(VOICE_EVENT));
122	}
123	export function onVoiceChange(listener: () => void) { window.addEventListener(VOICE_EVENT, listener); return () => window.removeEventListener(VOICE_EVENT, listener); }
124	/** Register a real voice provider (speech out, optionally speech in) and turn sound on. */
125	export function setVoice(next: VoiceAdapter | null) { stopSpeaking(); stopListening(); adapter = next ?? defaultVoice; setMuted(false); }
126	/**
127	 * Tap-to-talk; resolves with the transcript ('' when nothing was heard). A registered adapter that cannot listen
128	 * leaves the microphone to the default voice. Nothing is spoken aloud while the microphone is open.
129	 */
130	export async function listen(onPartial?: (text: string) => void): Promise<string> {
131	  openMics++;
132	  try { return await (adapter.listen ? adapter.listen(onPartial) : defaultVoice.listen(onPartial)); }
133	  finally { openMics--; }
134	}
135	/** End the current listen(); its promise then resolves with what was heard. */
136	export function stopListening() { if (adapter.listen) adapter.stopListening?.(); else defaultVoice.stopListening(); }
137	export function stopSpeaking() { cancel?.(); }
138	/** Resolves when the line has been spoken; when muted (or while the microphone is open) it waits a short reading pause instead. */
139	export function speak(text: string): Promise<void> {
140	  stopSpeaking();
141	  if (!text.trim()) return Promise.resolve();
142	  return new Promise<void>(resolve => {
143	    const audible = !muted && openMics === 0; let settled = false;
144	    const done = () => { if (settled) return; settled = true; window.clearTimeout(timer); if (cancel === abort) cancel = null; resolve(); };
145	    const abort = () => { if (audible) adapter.stop(); done(); };
146	    // Safety net: never let a stuck audio backend freeze a walkthrough.
147	    const timer = window.setTimeout(done, audible ? 8000 + text.length * 110 : Math.min(4200, 900 + text.length * 30));
148	    cancel = abort;
149	    if (audible) adapter.speak(text).then(done, done);
150	  });
151	}
152	// Narration lines travel as a window event, not through module state: a dev-server hot update re-creates this module,
153	// and a listener registered on the old copy would silently stop receiving lines (bubbles missing while the voice still speaks).
154	const NARRATION_EVENT = 'brickvision:narration';
155	export function onNarration(listener: (text: string) => void) {
156	  const handle = (event: Event) => listener((event as CustomEvent<string>).detail);
157	  window.addEventListener(NARRATION_EVENT, handle);
158	  return () => window.removeEventListener(NARRATION_EVENT, handle);
159	}
160	/** A walkthrough line: show it in the chat and speak it. */
161	export function narrate(text: string): Promise<void> { window.dispatchEvent(new CustomEvent<string>(NARRATION_EVENT, { detail: text })); return speak(text); }
162

1	/**
2	 * Gradium voice for BrickBuddy: streaming text-to-speech and tap-to-talk speech-to-text.
3	 * The browser only ever holds a single-use token minted by our backend, never the API key.
4	 */
5	import { post } from './api';
6	import type { VoiceAdapter } from './agent';
7	
8	/** End of turn: Gradium's 2 s-horizon inactivity probability must stay above the threshold this many steps (80 ms each) in a row. */
9	export const VAD_THRESHOLD = 0.6;
10	export const VAD_CONSECUTIVE_STEPS = 4;
11	/** Hard cap on one utterance. */
12	export const MAX_LISTEN_MS = 30000;
13	/** If nothing was transcribed after this long and the input is flat, stop and say so. */
14	const DEAF_CHECK_MS = 6000;
15	const SILENCE_PEAK = 0.003;
16	const VIRTUAL_INPUT = /hue sync|teams|zoom|blackhole|loopback|soundflower|virtual|aggregate|multi-output|krisp|obs/i;
17	
18	const TTS_URL = 'wss://api.gradium.ai/api/speech/tts';
19	const STT_URL = 'wss://api.gradium.ai/api/speech/asr';
20	const TTS_RATE = 48000; // output_format "pcm": 48 kHz, 16-bit, mono
21	const STT_RATE = 24000; // input_format "pcm": 24 kHz, 16-bit, mono
22	const CHUNK_SAMPLES = 1920; // 80 ms at 24 kHz
23	const SCHEDULE_AHEAD_S = 0.06;
24	const FLUSH_TIMEOUT_MS = 2500; // how long to wait for the last words after end_of_stream
25	const MAX_BACKLOG_CHUNKS = 50; // audio captured while the token and socket are still on their way (4 s)
26	
27	/** Gradium cannot be used at all (not configured, token rejected, unreachable): callers should fall back. */
28	export class VoiceUnavailable extends Error {
29	  constructor(message = 'Voice is not available right now.') { super(message); this.name = 'VoiceUnavailable'; }
30	}
31	
32	interface VoiceToken { token: string; voice_id: string; }
33	interface TtsMessage { type?: string; audio?: string; sample_rate?: number; message?: string; }
34	interface SttMessage { type?: string; text?: string; message?: string; vad?: { inactivity_prob?: number }[]; }
35	
36	/** One single-use token per WebSocket connection. It expires within seconds: mint it right before connecting, never cache it. */
37	async function getToken(): Promise<VoiceToken> {
38	  try {
39	    const body = await post<VoiceToken>('/voice/token');
40	    if (typeof body?.token !== 'string' || !body.token) throw new Error('The voice service returned no token.');
41	    return body;
42	  } catch (error) {
43	    throw new VoiceUnavailable(error instanceof Error ? error.message : undefined);
44	  }
45	}
46	const openSocket = (url: string, token: string) => new WebSocket(`${url}?token=${encodeURIComponent(token)}`);
47	function send(socket: WebSocket | null, message: object) {
48	  if (socket?.readyState === WebSocket.OPEN) socket.send(JSON.stringify(message));
49	}
50	function closeSocket(socket: WebSocket | null) {
51	  if (!socket) return;
52	  socket.onopen = socket.onmessage = socket.onerror = socket.onclose = null;
53	  try { socket.close(); } catch { /* Already closed. */ }
54	}
55	/** Server frames are untrusted JSON: anything unreadable becomes an empty message. */
56	function parse<T extends object>(data: unknown): T {
57	  try { const value: unknown = JSON.parse(String(data)); if (value && typeof value === 'object') return value as T; } catch { /* Not JSON. */ }
58	  return {} as T;
59	}
60	
61	/** base64 of 16-bit signed little-endian PCM -> float samples. */
62	function decodePcm16(base64: string): Float32Array {
63	  const binary = atob(base64);
64	  const samples = new Float32Array(binary.length >> 1);
65	  for (let i = 0; i < samples.length; i++) {
66	    const value = binary.charCodeAt(2 * i) | (binary.charCodeAt(2 * i + 1) << 8);
67	    samples[i] = (value > 0x7fff ? value - 0x10000 : value) / 32768;
68	  }
69	  return samples;
70	}
71	/** Float samples -> base64 of 16-bit signed little-endian PCM. */
72	function encodePcm16(samples: Float32Array): string {
73	  const bytes = new Uint8Array(samples.length * 2);
74	  const view = new DataView(bytes.buffer);
75	  for (let i = 0; i < samples.length; i++) {
76	    const sample = Math.max(-1, Math.min(1, samples[i]));
77	    view.setInt16(i * 2, sample < 0 ? sample * 32768 : sample * 32767, true);
78	  }
79	  let binary = '';
80	  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
81	  return btoa(binary);
82	}
83	/** Streaming linear resampler: it carries its read position across blocks, so nothing is dropped at block edges. */
84	function createResampler(fromRate: number, toRate: number): (input: Float32Array) => Float32Array {
85	  const step = fromRate / toRate;
86	  let position = 0; // Read position in the next block; -1 is the last sample of the previous block.
87	  let previous = 0;
88	  return input => {
89	    if (step === 1 || input.length === 0) return input;
90	    const output: number[] = [];
91	    for (; position < input.length - 1; position += step) {
92	      const index = Math.floor(position);
93	      const before = index < 0 ? previous : input[index];
94	      output.push(before + (input[index + 1] - before) * (position - index));
95	    }
96	    previous = input[input.length - 1];
97	    position -= input.length;
98	    return Float32Array.from(output);
99	  };
100	}
101	
102	// ---------------------------------------------------------------- text to speech
103	let player: AudioContext | null = null;
104	/** One shared output context, created lazily at the voice's own rate so chunks join without resampling seams. */
105	function playerContext(): AudioContext {
106	  if (!player) { try { player = new AudioContext({ sampleRate: TTS_RATE }); } catch { player = new AudioContext(); } }
107	  void player.resume().catch(() => undefined);
108	  return player;
109	}
110	// Browsers only let audio start after a user gesture, so wake the output on the first one.
111	if (typeof window !== 'undefined') {
112	  for (const gesture of ['click', 'keydown']) window.addEventListener(gesture, () => { playerContext(); }, { once: true, capture: true });
113	}
114	
115	let stopSpeech: (() => void) | null = null;
116	
117	function speak(text: string): Promise<void> {
118	  stop();
119	  return new Promise<void>((resolve, reject) => {
120	    const sources = new Set<AudioBufferSourceNode>();
121	    let socket: WebSocket | null = null;
122	    let sampleRate = TTS_RATE, playhead = 0, timer = 0;
123	    let started = false, ended = false, settled = false;
124	
125	    const settle = (error?: Error) => {
126	      if (settled) return;
127	      settled = true; window.clearTimeout(timer);
128	      if (stopSpeech === halt) stopSpeech = null;
129	      closeSocket(socket); socket = null;
130	      if (error) reject(error); else resolve();
131	    };
132	    const halt = () => {
133	      sources.forEach(source => { try { source.stop(); } catch { /* Already ended. */ } });
134	      sources.clear(); settle();
135	    };
136	    // The stream is over: resolve once everything that was scheduled has actually been heard.
137	    const finish = () => {
138	      if (ended || settled) return;
139	      ended = true; closeSocket(socket); socket = null;
140	      const remaining = started ? Math.max(0, playhead - playerContext().currentTime) : 0;
141	      timer = window.setTimeout(() => settle(), remaining * 1000);
142	    };
143	    // A failure before any audio means Gradium is unusable; later on, just let the scheduled audio play out.
144	    const fail = (message: string) => {
145	      if (ended || settled) return;
146	      if (started) finish(); else settle(new VoiceUnavailable(message));
147	    };
148	    const play = (samples: Float32Array) => {
149	      if (!samples.length) return;
150	      const context = playerContext();
151	      const buffer = context.createBuffer(1, samples.length, sampleRate);
152	      buffer.getChannelData(0).set(samples);
153	      const source = context.createBufferSource();
154	      source.buffer = buffer; source.connect(context.destination);
155	      source.onended = () => { sources.delete(source); source.disconnect(); };
156	      playhead = Math.max(playhead, context.currentTime + SCHEDULE_AHEAD_S);
157	      source.start(playhead); playhead += buffer.duration;
158	      sources.add(source); started = true;
159	    };
160	
161	    stopSpeech = halt;
162	    getToken().then(({ token, voice_id }) => {
163	      if (settled) return;
164	      const ws = socket = openSocket(TTS_URL, token);
165	      // Gradium accepts the whole request up front, so there is no need to wait for "ready".
166	      ws.onopen = () => {
167	        send(ws, { type: 'setup', model_name: 'default', voice_id, output_format: 'pcm' });
168	        send(ws, { type: 'text', text }); send(ws, { type: 'end_of_stream' });
169	      };
170	      ws.onmessage = event => {
171	        const message = parse<TtsMessage>(event.data);
172	        if (message.type === 'ready') {
173	          const rate = Number(message.sample_rate);
174	          if (rate >= 8000 && rate <= 96000) sampleRate = rate;
175	        } else if (message.type === 'audio') { if (typeof message.audio === 'string') play(decodePcm16(message.audio)); }
176	        else if (message.type === 'end_of_stream') finish();
177	        else if (message.type === 'error') fail(message.message || 'Gradium could not speak that.');
178	      };
179	      // A bad token still connects and is then closed with 1008; a clean close just ends the stream.
180	      ws.onerror = () => fail('Could not reach the Gradium voice service.');
181	      ws.onclose = event => { if (event.code === 1000) finish(); else fail('Gradium closed the voice connection before any audio arrived.'); };
182	    }).catch((error: unknown) => settle(error instanceof VoiceUnavailable ? error : new VoiceUnavailable(error instanceof Error ? error.message : undefined)));
183	  });
184	}
185	/** Silence at once; the pending speak() resolves. Safe to call at any time. */
186	function stop() { stopSpeech?.(); }
187	
188	// ---------------------------------------------------------------- speech to text
189	// Hands raw microphone samples to the main thread, off the audio thread.
190	const CAPTURE_WORKLET = `
191	class Capture extends AudioWorkletProcessor {
192	  process(inputs) {
193	    const channel = inputs[0] && inputs[0][0];
194	    if (channel) this.port.postMessage(channel.slice(0));
195	    return true;
196	  }
197	}
198	registerProcessor("capture", Capture);
199	`;
200	function microphoneError(error: unknown): Error {
201	  const name = error instanceof Error ? error.name : '';
202	  if (name === 'NotAllowedError' || name === 'SecurityError') return new Error('The microphone is blocked. Allow it for this page, or type instead.');
203	  if (name === 'NotFoundError') return new Error('I could not find a microphone. Type instead!');
204	  return new Error('I could not start the microphone. Type instead!');
205	}
206	
207	let stopHearing: (() => void) | null = null;
208	/** Live input level (0..1 peak per 80 ms) for the mic button, as a window event. */
209	export const MIC_LEVEL_EVENT = 'brickvision:mic-level';
210	const reportLevel = (level: number) => window.dispatchEvent(new CustomEvent<number>(MIC_LEVEL_EVENT, { detail: level }));
211	
212	/** Tap-to-talk: resolves with the transcript when the speaker stops, stopListening() is called or MAX_LISTEN_MS passes. */
213	function listen(onPartial?: (text: string) => void): Promise<string> {
214	  if (stopHearing) return Promise.reject(new Error('I am already listening.'));
215	  return new Promise<string>((resolve, reject) => {
216	    const segments: string[] = [];
217	    const chunk = new Float32Array(CHUNK_SAMPLES);
218	    const backlog: string[] = []; // Encoded chunks captured before Gradium was ready.
219	    let filled = 0, quietSteps = 0, maxTimer = 0, flushTimer = 0, deafTimer = 0;
220	    let chunks = 0, loudest = 0, micLabel = '';
221	    let ready = false, ending = false, settled = false;
222	    let stream: MediaStream | null = null, capture: AudioContext | null = null, socket: WebSocket | null = null;
223	    let nodes: AudioNode[] = [];
224	
225	    /** Stop the microphone and the capture graph. Idempotent. */
226	    const release = () => {
227	      nodes.forEach(node => node.disconnect()); nodes = [];
