289	
290	      const source = context.createMediaStreamSource(microphone);
291	      const worklet = new AudioWorkletNode(context, 'capture');
292	      const silence = context.createGain(); silence.gain.value = 0;
293	      const resample = createResampler(context.sampleRate, STT_RATE);
294	      worklet.port.onmessage = (event: MessageEvent<Float32Array>) => { if (!ending && !settled) feed(resample(event.data)); };
295	      source.connect(worklet); worklet.connect(silence).connect(context.destination);
296	      nodes = [source, worklet, silence];
297	      maxTimer = window.setTimeout(end, MAX_LISTEN_MS);
298	      // Say why nothing is being written instead of listening to nothing forever.
299	      deafTimer = window.setTimeout(() => {
300	        if (segments.length || ending || settled) return;
301	        if (chunks === 0) settle(new Error('This browser is not delivering microphone audio. Reload the page or use Chrome, or type instead.'));
302	        else if (loudest < SILENCE_PEAK) settle(new Error(`I only hear silence from ${micLabel ? `"${micLabel}"` : 'the microphone'}. Pick your real microphone in the browser's site settings (the icon left of the address bar), or type instead.`));
