306	      const { token } = await getToken();
307	      if (settled) return;
308	      const ws = socket = openSocket(STT_URL, token);
309	      ws.onopen = () => send(ws, { type: 'setup', model_name: 'default', input_format: 'pcm', json_config: { language: 'en' } });
310	      ws.onmessage = event => {
311	        const message = parse<SttMessage>(event.data);
312	        switch (message.type) {
313	          case 'ready':
314	            ready = true;
315	            backlog.splice(0).forEach(audio => send(ws, { type: 'audio', audio }));
316	            break;
317	          case 'text':
318	            if (typeof message.text === 'string' && message.text.trim()) segments.push(message.text.trim());
319	            onPartial?.(segments.join(' '));
320	            break;
321	          case 'step': case 'vad': { // "vad" is the legacy name of the same message.
322	            const quiet = Number(message.vad?.[2]?.inactivity_prob) > VAD_THRESHOLD;
323	            quietSteps = quiet ? quietSteps + 1 : 0;
324	            if (segments.length > 0 && quietSteps >= VAD_CONSECUTIVE_STEPS) end();
325	            break;
326	          }
327	          case 'end_of_stream': settle(); break;
328	          case 'error': {
329	            const reason = `Gradium could not transcribe that${message.message ? `: ${message.message}` : '.'}`;
330	            settle(ready ? new Error(reason) : new VoiceUnavailable(reason));
331	            break;
332	          }
333	        }
334	      };
335	      // A bad token still connects and is then closed with 1008: before "ready" that means Gradium is unusable.
336	      // Once listening has begun, a dropped connection just ends the turn with what was heard.
337	      ws.onerror = () => settle(ready ? undefined : new VoiceUnavailable('Could not reach the Gradium voice service.'));
338	      ws.onclose = event => settle(ready || event.code === 1000 ? undefined : new VoiceUnavailable('Gradium refused the voice connection.'));
339	    };
340	
341	    stopHearing = end;
342	    start().catch((error: unknown) => settle(error instanceof Error ? error : new Error('Voice input failed.')));
343	  });
344	}
