12	import './chat.css';
13	
14	interface Message extends ChatTurn { actions?: ViewerAction[]; narration?: boolean; error?: boolean; }
15	const SUGGESTIONS = ['Take me to step 5', 'Walk me through the next 3 steps', 'Spin it around'];
16	
17	export default function ChatPanel({ controller }: { controller: RefObject<ViewerController> }) {
18	  const [open, setOpen] = useState(false);
19	  const [messages, setMessages] = useState<Message[]>([]);
20	  const [draft, setDraft] = useState('');
21	  const [busy, setBusy] = useState(false); const [listening, setListening] = useState(false);
22	  const [silent, setSilent] = useState(isMuted);
23	  const list = useRef<HTMLDivElement>(null); const input = useRef<HTMLInputElement>(null);
24	  const history = useRef<Message[]>([]); const turn = useRef(0); const thinking = useRef(false);
25	  const append = (message: Message) => { history.current = [...history.current, message]; setMessages(history.current); };
26	  const send = async (raw: string) => {
27	    const text = raw.trim();
28	    if (!text || thinking.current) return;
29	    const mine = ++turn.current;
30	    stopSpeaking(); setOpen(true); setDraft('');
31	    void controller.current.run({ type: 'stop' }); // A new request ends any walkthrough still playing.
32	    append({ role: 'user', text });
33	    // Only send turns the API accepts (non-empty, bounded), or one odd reply would poison every later request.
34	    const turns = history.current.filter(m => !m.error && m.text.trim()).map(({ role, text }) => ({ role, text: text.slice(0, 2000) })).slice(-14);
35	    thinking.current = true; setBusy(true);
36	    try {
37	      const result = await askAgent(turns, controller.current.context());
38	      if (turn.current !== mine) return; // Superseded, or the viewer was closed: drop the stale answer.
39	      thinking.current = false; setBusy(false);
40	      const reply = result.reply.trim() || (result.actions.length ? 'On it!' : 'Sorry, I did not catch that. Could you say it again?');
41	      append({ role: 'assistant', text: reply, actions: result.actions });
42	      const act = async () => { for (const action of result.actions) { if (turn.current !== mine) return; await controller.current.run(action); } };
43	      // A narrated walkthrough speaks per step, so the intro line goes first; otherwise talk while acting.
44	      if (result.actions.some(action => action.type === 'play_steps')) { await speak(reply); await act(); }
45	      else await Promise.all([speak(reply), act()]);
46	    } catch (error) {
47	      if (turn.current === mine) append({ role: 'assistant', text: error instanceof Error ? error.message : 'Something went wrong. Please try again.', error: true });
48	    } finally { if (turn.current === mine) { thinking.current = false; setBusy(false); } } // An older turn must not unlock a newer one.
49	  };
50	  const sendRef = useRef(send); sendRef.current = send;
51	  // Mic toggle: tap to talk, tap again (or just stop talking) to send what was heard.
52	  const hearing = useRef(false);
53	  const talk = async () => {
54	    if (hearing.current) { stopListening(); return; }
55	    if (thinking.current) return;
56	    stopSpeaking(); // BrickBuddy's own voice must not be transcribed.
57	    hearing.current = true; setListening(true);
