71	  }, []);
72	  useEffect(() => onNarration(text => append({ role: 'assistant', text, narration: true })), []);
73	  useEffect(() => onVoiceChange(() => setSilent(isMuted())), []);
74	  useEffect(() => { list.current?.scrollTo({ top: list.current.scrollHeight, behavior: 'smooth' }); }, [messages, busy, open]);
75	  useEffect(() => { if (open) input.current?.focus(); }, [open]);
