77	  useEffect(() => {
78	    const scope = window as unknown as { brickvision?: unknown };
79	    scope.brickvision = { send: (text: string) => sendRef.current(text), run: (action: ViewerAction) => controller.current.run(action),
80	      context: () => controller.current.context(), setVoice, speak, stop: stopSpeaking, listen, stopListening, open: () => setOpen(true) };
81	    return () => { delete scope.brickvision; };
82	  }, [controller]);
83	  // While listening the draft is the live transcript: Enter ends the turn, which sends it once.
84	  const submit = (event: FormEvent) => { event.preventDefault(); if (hearing.current) stopListening(); else void send(draft); };
85	  return <div className={`buddy${open ? ' open' : ''}`}>
86	    {open && <section className="buddy-panel" aria-label="Build buddy chat">
87	      <header className="buddy-header">
88	        <span className="buddy-avatar" aria-hidden="true"><IconSparkles size={20}/></span>
89	        <div className="buddy-title"><strong>BrickBuddy</strong><small role="status">{listening ? 'Listening… tap mic to send' : busy ? 'Thinking…' : 'Ask me to move, explain or spin the model'}</small></div>
90	        <button type="button" className={`buddy-icon${silent ? ' voice-off' : ''}`} aria-pressed={!silent} aria-label={silent ? 'Turn voice on' : 'Turn voice off'} title={silent ? 'Turn voice on' : 'Turn voice off'} onClick={() => setMuted(!silent)}>{silent ? <><IconVolumeOff size={17}/>Voice off</> : <IconVolume size={19}/>}</button>
91	        <button type="button" className="buddy-icon" aria-label="Close chat" title="Close chat" onClick={() => { stopListening(); setOpen(false); }}><IconX size={19}/></button>
92	      </header>
93	      <div className="buddy-messages" ref={list} aria-live="polite">
94	        {messages.length === 0 && <div className="buddy-empty"><p>Hi! I can drive the 3D model while your hands are busy. Try:</p>{SUGGESTIONS.map(text => <button type="button" key={text} onClick={() => void send(text)}>{text}</button>)}</div>}
95	        {messages.map((message, i) => <div key={i} className={`buddy-msg ${message.role}${message.error ? ' error' : ''}${message.narration ? ' narration' : ''}`}>
96	          <p>{message.text}</p>
97	          {message.actions && message.actions.length > 0 && <div className="buddy-chips">{message.actions.map((action, k) => <span key={k}>{describeAction(action)}</span>)}</div>}
98	        </div>)}
99	        {busy && <div className="buddy-msg assistant typing" aria-label="BrickBuddy is thinking"><span/><span/><span/></div>}
100	      </div>
101	      <form className="buddy-form" onSubmit={submit}>
102	        <button ref={mic} type="button" className={`buddy-mic${listening ? ' live' : ''}`} aria-pressed={listening} aria-label={listening ? 'Stop listening and send' : 'Talk to BrickBuddy'} title={listening ? 'Stop listening and send' : 'Talk to BrickBuddy'} disabled={busy && !listening} onClick={() => void talk()}><IconMicrophone size={20}/></button>
103	        <input ref={input} value={draft} readOnly={listening} onChange={event => setDraft(event.target.value)} placeholder={listening ? 'Listening…' : 'Ask BrickBuddy…'} aria-label="Message BrickBuddy" autoComplete="off"/>
104	        <button type="submit" className="buddy-send" aria-label="Send" disabled={busy || !draft.trim()}><IconSend2 size={19}/></button>
105	      </form>
106	    </section>}
107	    <button type="button" className="buddy-launcher" aria-expanded={open} aria-label={open ? 'Hide build buddy' : 'Chat with your build buddy'} title="BrickBuddy" onClick={() => { if (open) stopListening(); setOpen(value => !value); }}>{open ? <IconX size={26}/> : <IconMessageChatbot size={28}/>}</button>
108	  </div>;
109	}
