import { useEffect, useRef, useState } from 'react';
import { askAssistant, type AssistantAction, type AssistantContext, type AssistantTurn } from './assistant';
import { VoiceSession, type VoiceState } from './session';

const HISTORY_TURNS = 12;

export interface Assistant {
  voiceState: VoiceState;
  voiceActive: boolean;
  turns: AssistantTurn[];
  partial: string;
  error: string | null;
  pending: boolean;
  muted: boolean;
  toggleVoice: () => void;
  toggleMute: () => void;
  submitText: (text: string) => void;
}

/** One assistant for the whole app, so voice survives moving between landing, booklet and tutorial. */
export function useAssistant(getContext: () => AssistantContext, perform: (action: AssistantAction) => Promise<void> | void): Assistant {
  const [voiceState, setVoiceState] = useState<VoiceState>('idle');
  const [turns, setTurns] = useState<AssistantTurn[]>([]);
  const [partial, setPartial] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const [muted, setMuted] = useState(false);
  const session = useRef<VoiceSession | null>(null);
  const history = useRef<AssistantTurn[]>([]);
  const latest = useRef({getContext, perform});
  latest.current = {getContext, perform};

  useEffect(() => () => session.current?.stop(), []);

  const push = (turn: AssistantTurn) => {
    history.current = [...history.current, turn];
    setTurns(history.current);
  };

  async function handle(text: string): Promise<string | null> {
    push({role: 'user', text});
    setPending(true);
    setError(null);
    try {
      const reply = await askAssistant(history.current.slice(-HISTORY_TURNS), latest.current.getContext());
      push({role: 'assistant', text: reply.text});
      if (reply.action.type !== 'none') {
        try { await latest.current.perform(reply.action); }
        catch (failure) { setError(failure instanceof Error ? failure.message : 'That navigation could not be completed.'); }
      }
      return reply.text;
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : 'The assistant could not reply.');
      return null;
    } finally {
      setPending(false);
    }
  }

  const voiceActive = voiceState !== 'idle' && voiceState !== 'error';

  function toggleVoice() {
    if (session.current && voiceActive) {
      session.current.stop();
      session.current = null;
      setMuted(false);
      return;
    }
    setError(null);
    setPartial('');
    setMuted(false);
    session.current = new VoiceSession({onState: setVoiceState, onPartial: setPartial, onError: setError, onUtterance: handle});
    void session.current.start();
  }

  function toggleMute() {
    if (!session.current || !voiceActive) return;
    session.current.setMuted(!muted);
    setMuted(!muted);
  }

  function submitText(text: string) {
    const value = text.trim();
    if (!value || pending) return;
    if (session.current && voiceActive) session.current.submit(value);
    else void handle(value);
  }

  return {voiceState, voiceActive, turns, partial, error, pending, muted: muted && voiceActive, toggleVoice, toggleMute, submitText};
}

import { post } from '../api';
import type { ControlInfo } from './controls';

export type AssistantAction =
  | {type: 'none'}
  | {type: 'find_set'; set_number: string}
  | {type: 'open_tutorial'; set_number: string; guide_id?: string}
  | {type: 'go_to_step'; step: number}
  | {type: 'click'; control_id: string}
  | {type: 'close_booklet' | 'go_home' | 'how_it_works' | 'next_step' | 'previous_step' | 'replay_step' | 'play_build'};

export interface StepCommand { type: 'next_step' | 'previous_step' | 'go_to_step' | 'replay_step' | 'play_build'; step?: number; token: number }
export interface StepContext { index: number; total: number; label: string; main_step_numbers: number[] }
export interface AssistantContext {
  screen: 'landing' | 'booklet' | 'tutorial';
  set_number?: string | null;
  guide_id?: string | null;
  guides?: {guide_id: string; label: string; tutorial_available: boolean}[];
  step?: StepContext | null;
  controls?: ControlInfo[];
}
export interface AssistantTurn { role: 'user' | 'assistant'; text: string }
export interface AssistantReply { text: string; action: AssistantAction }

const SIMPLE = new Set(['close_booklet', 'go_home', 'how_it_works', 'next_step', 'previous_step', 'replay_step', 'play_build']);
const SET_NUMBER = /^\d{4,7}$/;

/** The server validates actions too; the browser still refuses anything malformed. */
export function parseAction(value: unknown): AssistantAction {
  if (!value || typeof value !== 'object') return {type: 'none'};
  const action = value as Record<string, unknown>;
  const type = action.type;
  if (typeof type !== 'string') return {type: 'none'};
  if (SIMPLE.has(type)) return {type} as AssistantAction;
  if (type === 'find_set' && typeof action.set_number === 'string' && SET_NUMBER.test(action.set_number)) return {type, set_number: action.set_number};
  if (type === 'open_tutorial' && typeof action.set_number === 'string' && SET_NUMBER.test(action.set_number)) {
    return typeof action.guide_id === 'string' && /^[a-z0-9-]{1,64}$/.test(action.guide_id)
      ? {type, set_number: action.set_number, guide_id: action.guide_id} : {type, set_number: action.set_number};
  }
  if (type === 'click' && typeof action.control_id === 'string' && /^c\d{1,3}$/.test(action.control_id)) return {type, control_id: action.control_id};
  if (type === 'go_to_step' && Number.isInteger(action.step) && (action.step as number) > 0) return {type, step: action.step as number};
  return {type: 'none'};
}

export async function askAssistant(messages: AssistantTurn[], context: AssistantContext): Promise<AssistantReply> {
  const reply = await post<{text?: unknown; action?: unknown}>('/voice/reply', {messages, context});
  if (typeof reply.text !== 'string' || !reply.text.trim()) throw new Error('The assistant returned an empty reply.');
  return {text: reply.text, action: parseAction(reply.action)};
}

export function stepIndexFor(steps: {main_step_number: number | null}[], step: number): number {
  return steps.findIndex(item => item.main_step_number === step);
}

import { useSyncExternalStore } from 'react';

/** Shared by every dock instance (booklet dialog, viewer), so moving or minimizing it survives navigation. */
export interface DockPosition { x: number; y: number }
export interface DockState { minimized: boolean; position: DockPosition | null }

const KEY = 'guide2build.voiceDock';
const MARGIN = 8;
const listeners = new Set<() => void>();

function validPosition(value: unknown): value is DockPosition {
  const item = value as DockPosition | null;
  return !!item && Number.isFinite(item.x) && Number.isFinite(item.y);
}

function load(): DockState {
  try {
    const value = JSON.parse(localStorage.getItem(KEY) ?? 'null');
    if (typeof value?.minimized === 'boolean') return {minimized: value.minimized, position: validPosition(value.position) ? value.position : null};
  } catch { /* unreadable storage falls back to defaults */ }
  return {minimized: true, position: null};
}

let state: DockState = typeof window === 'undefined' ? {minimized: true, position: null} : load();

export function setDockState(patch: Partial<DockState>, persist = true) {
  state = {...state, ...patch};
  if (persist) { try { localStorage.setItem(KEY, JSON.stringify(state)); } catch { /* private mode: keep in memory */ } }
  listeners.forEach(listener => listener());
}

export function useDockState(): DockState {
  return useSyncExternalStore(listener => { listeners.add(listener); return () => { listeners.delete(listener); }; }, () => state, () => state);
}

export function clampPosition(x: number, y: number, width: number, height: number): DockPosition {
  return {
    x: Math.round(Math.min(Math.max(MARGIN, x), Math.max(MARGIN, window.innerWidth - width - MARGIN))),
    y: Math.round(Math.min(Math.max(MARGIN, y), Math.max(MARGIN, window.innerHeight - height - MARGIN))),
  };
}

import IconMicrophone from '@tabler/icons-react/dist/esm/icons/IconMicrophone.mjs';
import IconMicrophoneOff from '@tabler/icons-react/dist/esm/icons/IconMicrophoneOff.mjs';
import IconPlayerStop from '@tabler/icons-react/dist/esm/icons/IconPlayerStop.mjs';
import IconGridDots from '@tabler/icons-react/dist/esm/icons/IconGridDots.mjs';
import IconMinus from '@tabler/icons-react/dist/esm/icons/IconMinus.mjs';
import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type FormEvent, type KeyboardEvent, type PointerEvent } from 'react';
import { clampPosition, setDockState, useDockState } from '../voice/dockState';
import { GRADIUM_VOICE_NAME, type VoiceState } from '../voice/session';
import type { Assistant } from '../voice/useAssistant';
import './voice.css';

const STATUS: Record<VoiceState, string> = {
  idle: 'Say or type where to go: “open the plane tutorial”, “next step”.',
  connecting: 'Connecting to your microphone…',
  listening: 'Listening — try “go to step 3” or “go home”.',
  thinking: 'Thinking…',
  speaking: `${GRADIUM_VOICE_NAME} is speaking…`,
  error: 'Voice chat stopped.',
};
const MUTED: Partial<Record<VoiceState, string>> = {
  listening: 'Microphone muted — type a command, or unmute to talk.',
  thinking: 'Microphone muted · thinking…',
  speaking: `Microphone muted · ${GRADIUM_VOICE_NAME} is speaking…`,
};

export default function VoiceChat({assistant, variant = 'hero'}: {assistant: Assistant; variant?: 'hero' | 'dock'}) {
  const {voiceState, voiceActive, turns, partial, error, pending, muted, toggleVoice, toggleMute, submitText} = assistant;
  const [draft, setDraft] = useState('');
  const dock = useDockState();
  const box = useRef<HTMLDivElement>(null);
  const drag = useRef<{dx: number; dy: number} | null>(null);
  const supported = typeof window !== 'undefined' && !!navigator.mediaDevices?.getUserMedia && 'AudioWorkletNode' in window;
  const state: VoiceState = pending && !voiceActive ? 'thinking' : voiceState;
  const status = error ?? (!supported ? 'Voice needs microphone support; you can still type a command.'
    : (muted && MUTED[state]) || STATUS[state]);
  const recent = turns.slice(partial ? -1 : -2);

  function submit(event: FormEvent) {
    event.preventDefault();
    submitText(draft);
    setDraft('');
  }

  const isDock = variant === 'dock';
  const minimized = isDock && dock.minimized;

  // Keep the dock on screen when it changes size (minimize/expand) or the window shrinks.
  useLayoutEffect(() => {
    if (!isDock || !dock.position || !box.current) return;
    const {width, height} = box.current.getBoundingClientRect();
    const next = clampPosition(dock.position.x, dock.position.y, width, height);
    if (next.x !== dock.position.x || next.y !== dock.position.y) setDockState({position: next}, false);
  });
  useEffect(() => {
    if (!isDock) return;
    const refit = () => { const current = box.current?.getBoundingClientRect(); if (current && dock.position) setDockState({position: clampPosition(current.left, current.top, current.width, current.height)}, false); };
    window.addEventListener('resize', refit);
    return () => window.removeEventListener('resize', refit);
  }, [isDock, dock.position]);

  function startDrag(event: PointerEvent<HTMLButtonElement>) {
    if (!box.current || event.button !== 0) return;
    const rect = box.current.getBoundingClientRect();
    drag.current = {dx: event.clientX - rect.left, dy: event.clientY - rect.top};
    event.currentTarget.setPointerCapture(event.pointerId);
    event.preventDefault();
  }
  function moveDrag(event: PointerEvent<HTMLButtonElement>) {
    if (!drag.current || !box.current) return;
    const {width, height} = box.current.getBoundingClientRect();
    setDockState({position: clampPosition(event.clientX - drag.current.dx, event.clientY - drag.current.dy, width, height)}, false);
  }
  function endDrag(event: PointerEvent<HTMLButtonElement>) {
    if (!drag.current) return;
    drag.current = null;
    event.currentTarget.releasePointerCapture(event.pointerId);
    setDockState({});
  }
  function nudge(event: KeyboardEvent<HTMLButtonElement>) {
    const step = event.shiftKey ? 80 : 24;
    const delta = {ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step]}[event.key];
    if (!delta || !box.current) return;
    event.preventDefault();
    const rect = box.current.getBoundingClientRect();
    setDockState({position: clampPosition(rect.left + delta[0], rect.top + delta[1], rect.width, rect.height)});
  }

  const placed: CSSProperties | undefined = isDock && dock.position ? {left: dock.position.x, top: dock.position.y, right: 'auto', bottom: 'auto'} : undefined;
  const grip = isDock && <button type="button" className="voice-grip" aria-label="Move build helper (drag, or use arrow keys)" title="Drag to move"
    onPointerDown={startDrag} onPointerMove={moveDrag} onPointerUp={endDrag} onPointerCancel={endDrag} onKeyDown={nudge}>
    <IconGridDots size={16} stroke={2.4} aria-hidden="true"/>
  </button>;

  // The dock floats over working controls, so it can shrink to a small pill that still shows the voice state.
  if (minimized) return <div ref={box} style={placed} className={`voice-chat voice-dock voice-collapsed voice-${state}${muted ? ' voice-muted' : ''}`}>
    {grip}
    <button type="button" className="voice-button" onClick={() => setDockState({minimized: false})} aria-label="Open build helper" aria-expanded={false}
      title={voiceActive ? status : 'Open build helper'}>
      <span className="voice-orb" aria-hidden="true">
        <span className="voice-ring"/><span className="voice-ring delay"/>
        {muted ? <IconMicrophoneOff size={22} stroke={2.2}/> : <IconMicrophone size={22} stroke={2.2}/>}
      </span>
    </button>
  </div>;

  return <div ref={box} style={placed} className={`voice-chat voice-${variant} voice-${state}${muted ? ' voice-muted' : ''}`}>
    {isDock && <div className="voice-dock-bar">
      {grip}
      <button type="button" className="voice-hide" onClick={() => setDockState({minimized: true})} aria-label="Minimize build helper" aria-expanded={true} title="Minimize">
        <IconMinus size={16} stroke={2.4} aria-hidden="true"/>
      </button>
    </div>}
    <div className="voice-row">
      <button type="button" className="voice-button" onClick={toggleVoice} disabled={!supported} aria-pressed={voiceActive}
        aria-label={voiceActive ? 'Stop voice chat' : 'Start voice chat'}>
        <span className="voice-orb" aria-hidden="true">
          <span className="voice-ring"/><span className="voice-ring delay"/>
          {voiceActive ? <IconPlayerStop size={variant === 'dock' ? 20 : 24} stroke={2.2}/> : <IconMicrophone size={variant === 'dock' ? 22 : 26} stroke={2.2}/>}
        </span>
      </button>
      {voiceActive && <button type="button" className="voice-mute" onClick={toggleMute} aria-pressed={muted}
        aria-label={muted ? 'Unmute microphone' : 'Mute microphone'} title={muted ? 'Unmute microphone' : 'Mute microphone'}>
        {muted ? <IconMicrophoneOff size={18} stroke={2.2} aria-hidden="true"/> : <IconMicrophone size={18} stroke={2.2} aria-hidden="true"/>}
      </button>}
      <div className="voice-copy">
        <strong>{voiceActive ? 'Voice helper is on' : 'Talk to the build helper'}</strong>
        <span role="status" aria-live="polite">{status}</span>
      </div>
    </div>
    {(recent.length > 0 || partial) && <ol className="voice-transcript" aria-label="Assistant conversation">
      {recent.map((turn, index) => <li key={turns.length - recent.length + index} className={turn.role}><span>{turn.role === 'user' ? 'You' : GRADIUM_VOICE_NAME}</span>{turn.text}</li>)}
      {partial && <li className="user partial"><span>You</span>{partial}</li>}
    </ol>}
    <form className="voice-command" onSubmit={submit}>
      <label className="sr-only" htmlFor={`voice-command-${variant}`}>Type a command for the build helper</label>
      <input id={`voice-command-${variant}`} value={draft} onChange={event => setDraft(event.target.value)} maxLength={500}
        placeholder="Type a command…" autoComplete="off" disabled={pending}/>
      <button type="submit" className="secondary" disabled={pending || !draft.trim()}>Send</button>
    </form>
    {variant === 'hero' && <p className="voice-note">Voice by Gradium · navigation and replies by Gemini · microphone only while on</p>}
  </div>;
}

